#include <vector>
#include <cmath>
#include <cstddef>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses OpenMP in a thread-safe way for all thread counts.
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Build augmented dense matrix [A|b] for robust Gaussian elimination with pivoting.
    std::vector<double> aug(N * (N + 1), 0.0);

    // Parallel COO -> dense accumulation (duplicates in COO are safely summed via atomic).
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
        const size_t r = A[k].row;
        const size_t c = A[k].column;
        if (r < N && c < N) {
            #pragma omp atomic update
            aug[r * (N + 1) + c] += A[k].value;
        }
    }

    // Copy b into augmented column.
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        aug[static_cast<size_t>(i) * (N + 1) + N] = (static_cast<size_t>(i) < b.size()) ? b[static_cast<size_t>(i)] : 0.0;
    }

    // Ensure x has size N.
    x.assign(N, 0.0);

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Find pivot row (serial for simplicity and determinism).
        size_t pivot = k;
        double maxAbs = std::fabs(aug[k * (N + 1) + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(aug[i * (N + 1) + k]);
            if (v > maxAbs) {
                maxAbs = v;
                pivot = i;
            }
        }

        // If singular/near-singular, leave remaining vars at 0 and continue.
        if (maxAbs < eps) {
            continue;
        }

        // Swap rows if needed.
        if (pivot != k) {
            #pragma omp parallel for schedule(static)
            for (std::ptrdiff_t j = static_cast<std::ptrdiff_t>(k); j <= static_cast<std::ptrdiff_t>(N); ++j) {
                double tmp = aug[k * (N + 1) + static_cast<size_t>(j)];
                aug[k * (N + 1) + static_cast<size_t>(j)] = aug[pivot * (N + 1) + static_cast<size_t>(j)];
                aug[pivot * (N + 1) + static_cast<size_t>(j)] = tmp;
            }
        }

        const double pivotVal = aug[k * (N + 1) + k];

        // Eliminate rows below pivot in parallel; each thread writes distinct row i.
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            size_t i = static_cast<size_t>(ii);
            double factor = aug[i * (N + 1) + k] / pivotVal;
            aug[i * (N + 1) + k] = 0.0;
            for (size_t j = k + 1; j <= N; ++j) {
                aug[i * (N + 1) + j] -= factor * aug[k * (N + 1) + j];
            }
        }
    }

    // Back substitution (sequential due to dependency chain).
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        size_t i = static_cast<size_t>(ii);
        double diag = aug[i * (N + 1) + i];
        if (std::fabs(diag) < eps) {
            x[i] = 0.0;
            continue;
        }

        double sum = 0.0;
        #pragma omp parallel for reduction(+:sum) schedule(static)
        for (std::ptrdiff_t jj = static_cast<std::ptrdiff_t>(i) + 1; jj < static_cast<std::ptrdiff_t>(N); ++jj) {
            size_t j = static_cast<size_t>(jj);
            sum += aug[i * (N + 1) + j] * x[j];
        }

        x[i] = (aug[i * (N + 1) + N] - sum) / diag;
    }
}
